create table if not exists public.banking_products (product_id uuid primary key default gen_random_uuid(), product_code text not null unique, product_name text not null, product_category text not null, product_tier text, description text, eligibility_notes text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.customer_products (customer_product_id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(customer_id) on delete cascade, product_id uuid not null references public.banking_products(product_id), status text not null default 'active' check(status in ('active','inactive','closed','pending')), opened_at date, closed_at date, source text not null default 'manual' check(source in ('manual','import','demo')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(customer_id,product_id));
create table if not exists public.customer_value_scores (value_score_id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(customer_id) on delete cascade, assessment_date date not null default current_date, value_score numeric(7,2) not null check(value_score between 0 and 100), value_band text not null check(value_band in ('emerging','core','high_value','top_value')), transaction_value_90d numeric(18,2) not null default 0, transaction_count_90d integer not null default 0, average_balance_30d numeric(18,2) not null default 0, relationship_age_days integer not null default 0, revenue_contribution numeric(18,2), profitability_status text not null default 'not_available' check(profitability_status in ('measured','estimated','not_available')), score_components jsonb not null default '{}'::jsonb, calculated_at timestamptz not null default now(), unique(customer_id,assessment_date));
create table if not exists public.product_recommendations (recommendation_id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(customer_id) on delete cascade, product_id uuid not null references public.banking_products(product_id), recommendation_type text not null check(recommendation_type in ('cross_sell','up_sell')), propensity_score numeric(6,2) not null check(propensity_score between 0 and 100), priority text not null check(priority in ('low','medium','high')), rationale text not null, evidence jsonb not null default '{}'::jsonb, status text not null default 'suggested' check(status in ('suggested','presented','accepted','declined','converted','expired','dismissed')), generated_at timestamptz not null default now(), expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(customer_id,product_id,recommendation_type));
create table if not exists public.recommendation_outcomes (outcome_id uuid primary key default gen_random_uuid(), recommendation_id uuid not null references public.product_recommendations(recommendation_id) on delete cascade, outcome text not null check(outcome in ('presented','accepted','declined','converted','no_response')), recorded_by uuid references auth.users(id), outcome_notes text, outcome_at timestamptz not null default now());
create table if not exists public.business_insights (insight_id uuid primary key default gen_random_uuid(), insight_key text not null, insight_type text not null check(insight_type in ('customer_value','product_growth','retention','portfolio','data_quality')), title text not null, summary text not null, recommended_action text not null, severity text not null default 'info' check(severity in ('info','attention','critical')), metric_value numeric(18,2), metric_unit text, evidence jsonb not null default '{}'::jsonb, generated_by text not null default 'rules-v1', generated_at timestamptz not null default now(), is_active boolean not null default true, unique(insight_key,generated_by));
create table if not exists public.customer_churn_outcomes (churn_outcome_id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(customer_id) on delete cascade, outcome_date date not null, outcome text not null check(outcome in ('churned','retained','reactivated','unknown')), evidence_source text, notes text, recorded_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(customer_id,outcome_date));
create index if not exists idx_customer_products_customer_status on public.customer_products(customer_id,status);
create index if not exists idx_customer_value_rank on public.customer_value_scores(assessment_date,value_score desc);
create index if not exists idx_product_recommendations_status_score on public.product_recommendations(status,propensity_score desc);
create index if not exists idx_product_recommendations_customer on public.product_recommendations(customer_id,generated_at desc);
create index if not exists idx_business_insights_active on public.business_insights(is_active,generated_at desc);
create index if not exists idx_churn_outcomes_customer_date on public.customer_churn_outcomes(customer_id,outcome_date desc);
insert into public.banking_products(product_code,product_name,product_category,product_tier,description,eligibility_notes) values
('SAVINGS_PLUS','Savings account','savings','standard','Illustrative savings opportunity; confirm current BancABC product terms.','Subject to current bank product criteria and suitability.'),
('PREMIUM_BANKING','Premium banking package','account','premium','Higher-tier banking relationship opportunity.','Subject to current bank product criteria and suitability.'),
('INVESTMENT_SERVICES','Investment and wealth services','investment','specialist','Suitability-led investment services opportunity.','Requires suitability assessment and regulatory checks.'),
('INTERNATIONAL_BANKING','International banking services','payments','specialist','International payments and banking services opportunity.','Confirm service availability, fees and customer needs.'),
('BUSINESS_BANKING','Business banking services','business','specialist','Business banking opportunity for recurring business activity.','Requires business verification and eligibility checks.')
on conflict(product_code) do nothing;
do $$ declare t text; begin foreach t in array array['banking_products','customer_products','customer_value_scores','product_recommendations','recommendation_outcomes','business_insights','customer_churn_outcomes'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant all on public.%I to service_role',t); end loop; end $$;